# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">İSLAM TOPLUMUNU YÖNLENDİREN İLKELER: İYİLİK VE ADALET (3.2.4 &amp; 3.2.5)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">İyiliği Emretme, Kötülükten Sakındırma</text>\n  <text x="180" y="85" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">(Emir bi\'l-Ma\'rûf ve Nehiy ani\'l-Münker)</text>\n  <text x="32" y="108" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Ma\'rûf:</tspan> Din ve akl-ı selimin iyi, güzel</text>\n  <text x="42" y="123" font-size="10.5" fill="#14532d">ve faydalı gördüğü her türlü erdemli davranış.</text>\n  <text x="32" y="143" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Münker:</tspan> Dinin ve sağduyunun çirkin, zararlı</text>\n  <text x="42" y="158" font-size="10.5" fill="#14532d">ve haksız kabul ettiği kötülükler.</text>\n  <text x="32" y="178" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Kurumsal Yansıması:</tspan> Şehir ve çarşı düzenini,</text>\n  <text x="42" y="193" font-size="10.5" fill="#14532d">tartı-ölçü dürüstlüğünü ve genel ahlakı</text>\n  <text x="42" y="208" font-size="10.5" fill="#14532d">denetleyen <tspan font-weight="bold">Hisbe Teşkilatı (Muhtesip)</tspan>.</text>\n  <text x="180" y="228" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">Âl-i İmrân 104: "Hayırlı bir ümmet..."</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Hak ve Adaleti Gözetme İlkesi</text>\n  <text x="520" y="85" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">("el-Mülkü yebkâ ma\'a\'l-adl" - Mülkün Temeli)</text>\n  <text x="372" y="108" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Eşref-i Mahlûkat:</tspan> İnsan yaratılmışların en</text>\n  <text x="382" y="123" font-size="10.5" fill="#1e3a8a">şereflisidir; hakları doğuştan dokunulmazdır.</text>\n  <text x="372" y="143" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Zarûrât-ı Dîniyye (5 Temel Dokunulmazlık):</tspan></text>\n  <text x="382" y="158" font-size="10.5" font-weight="bold" fill="#1d4ed8">Can, Mal, Akıl, Din ve Nesil Güvenliği</text>\n  <text x="372" y="178" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Adalet Kurumları:</tspan> Bağımsız <tspan font-weight="bold">Kadı</tspan> mahkemeleri</text>\n  <text x="382" y="193" font-size="10.5" fill="#1e3a8a">ve halkın yöneticileri şikâyet edebildiği</text>\n  <text x="382" y="208" font-size="10.5" font-weight="bold" fill="#1e40af">Dîvân-ı Mezâlim (Yüksek Adalet Divanı).</text>\n  <text x="520" y="228" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">Nisâ 58 &amp; Mâide 8: Tarafsız ve adil şahitlik!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">İSLAM TOPLUMUNDA BİRLİKTE YAŞAMA KÜLTÜRÜ VE HUKUKİ TEMELLER</text>\n  <rect x="20" y="46" width="210" height="194" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">1. Medine Vesikası (622)</text>\n  <text x="32" y="92" font-size="10.5" fill="#78350f">• Hz. Peygamber\'in hicretten</text>\n  <text x="40" y="107" font-size="10.5" fill="#78350f">sonra Müslümanlar, Yahudiler</text>\n  <text x="40" y="122" font-size="10.5" fill="#78350f">ve diğer kabilelerle imzaladığı</text>\n  <text x="40" y="137" font-size="10.5" font-weight="bold" fill="#b45309">ilk yazılı toplumsal sözleşme.</text>\n  <text x="32" y="160" font-size="10.5" fill="#78350f">• Her grubun din ve vicdan</text>\n  <text x="40" y="175" font-size="10.5" fill="#78350f">hürriyeti, can ve mal güvenliği</text>\n  <text x="40" y="190" font-size="10.5" fill="#78350f">anayasal güvenceye alınmıştır.</text>\n  <text x="125" y="220" text-anchor="middle" font-size="10" font-weight="bold" fill="#92400e">Çoğulcu birlikte yaşama modeli</text>\n  <rect x="245" y="46" width="210" height="194" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">2. Zimmet Hukuku (Ehl-i Zimme)</text>\n  <text x="257" y="92" font-size="10.5" fill="#581c87">• İslam devletinin egemenliği</text>\n  <text x="265" y="107" font-size="10.5" fill="#581c87">altında yaşayan gayrimüslim</text>\n  <text x="265" y="122" font-size="10.5" fill="#581c87">vatandaşlara <tspan font-weight="bold">zimmî</tspan> denir.</text>\n  <text x="257" y="145" font-size="10.5" fill="#581c87">• İnanç, ibadet, mabet, eğitim</text>\n  <text x="265" y="160" font-size="10.5" fill="#581c87">ve özel hukuk özerkliği tanınır.</text>\n  <text x="257" y="182" font-size="10.5" fill="#581c87">• Örnekler: Hz. Ömer\'in <tspan font-weight="bold">Kudüs</tspan></text>\n  <text x="265" y="197" font-size="10.5" fill="#581c87"><tspan font-weight="bold">Emânnâmesi</tspan>, Endülüs (Kurtuba)</text>\n  <text x="265" y="212" font-size="10.5" fill="#581c87">ve Fatih\'in <tspan font-weight="bold">Bosna Ahidnâmesi</tspan>.</text>\n  <rect x="470" y="46" width="210" height="194" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">3. Osmanlı Millet Sistemi</text>\n  <text x="482" y="92" font-size="10.5" fill="#1e3a8a">• Toplumu ırk veya etnik kökene</text>\n  <text x="490" y="107" font-size="10.5" fill="#1e3a8a">göre değil, <tspan font-weight="bold">din ve mezhep</tspan></text>\n  <text x="490" y="122" font-size="10.5" fill="#1e3a8a">aidiyetine göre örgütleyen</text>\n  <text x="490" y="137" font-size="10.5" fill="#1e3a8a">toplumsal yönetim modelidir.</text>\n  <text x="482" y="160" font-size="10.5" fill="#1e3a8a">• Rum Ortodoks, Ermeni ve</text>\n  <text x="490" y="175" font-size="10.5" fill="#1e3a8a">Yahudi cemaatleri asırlarca</text>\n  <text x="490" y="190" font-size="10.5" fill="#1e3a8a">kendi dillerini ve kültürlerini</text>\n  <text x="490" y="205" font-size="10.5" font-weight="bold" fill="#1d4ed8">barış içinde korumuştur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">SOSYAL HAYATI OLUŞTURAN İLİŞKİLER: AİLE, KOMŞULUK VE MİSAFİRPERVERLİK</text>\n  <rect x="20" y="48" width="210" height="190" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="125" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">Aile ve Sıla-i Rahim</text>\n  <text x="32" y="95" font-size="10.5" fill="#7f1d1d">• Toplumun çekirdeği <tspan font-weight="bold">aile</tspan>dir;</text>\n  <text x="40" y="110" font-size="10.5" fill="#7f1d1d">meveddet (sevgi) ve rahmet</text>\n  <text x="40" y="125" font-size="10.5" fill="#7f1d1d">temeli üzerine kurulur (Rûm 21).</text>\n  <text x="32" y="148" font-size="10.5" fill="#7f1d1d">• <tspan font-weight="bold">Birrü\'l-vâlideyn:</tspan> Anne-babaya</text>\n  <text x="40" y="163" font-size="10.5" fill="#7f1d1d">iyilik ve hürmet (İsrâ 23).</text>\n  <text x="32" y="185" font-size="10.5" fill="#7f1d1d">• <tspan font-weight="bold">Sıla-i Rahim:</tspan> Akraba bağlarını</text>\n  <text x="40" y="200" font-size="10.5" fill="#7f1d1d">ziyaret ve yardımla koruma.</text>\n  <rect x="245" y="48" width="210" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Komşuluk Hukuku (Câr)</text>\n  <text x="257" y="95" font-size="10.5" fill="#14532d">• "Cebrâil bana komşuyu o kadar</text>\n  <text x="265" y="110" font-size="10.5" fill="#14532d">tavsiye etti ki komşuyu komşuya</text>\n  <text x="265" y="125" font-size="10.5" font-weight="bold" fill="#15803d">mirasçı kılacak sandım."</text>\n  <text x="257" y="148" font-size="10.5" fill="#14532d">• Gayrimüslim komşunun da</text>\n  <text x="265" y="163" font-size="10.5" fill="#14532d">komşuluk hakkı tamdır.</text>\n  <text x="257" y="185" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Mahalle Kültürü:</tspan> Gufran ve</text>\n  <text x="265" y="200" font-size="10.5" fill="#14532d">avarız vakıflarıyla dayanışma.</text>\n  <rect x="470" y="48" width="210" height="190" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="575" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Misafirperverlik (İkrâm)</text>\n  <text x="482" y="95" font-size="10.5" fill="#1e3a8a">• "Allah\'a ve ahiret gününe iman</text>\n  <text x="490" y="110" font-size="10.5" font-weight="bold" fill="#1d4ed8">eden misafirine ikram etsin."</text>\n  <text x="482" y="133" font-size="10.5" fill="#1e3a8a">• Hz. İbrahim (Halîlullah) misafir</text>\n  <text x="490" y="148" font-size="10.5" fill="#1e3a8a">cömertliğinin sembolüdür.</text>\n  <text x="482" y="170" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Kurumlar:</tspan> Misafirhaneler (tâbhâne),</text>\n  <text x="490" y="185" font-size="10.5" fill="#1e3a8a">imarethaneler, kervansaraylar</text>\n  <text x="490" y="200" font-size="10.5" fill="#1e3a8a">ve köy odaları geleneği.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
